        "망원동은 만리동길 카페·맛집 거리로 유명한 트렌디한 주거·상권 지역입니다. "
        "한강변 주거 지역과 골목 상권이 어우러져 있으며, 소규모 카페·바·음식점이 밀집되어 있습니다. "
