def build_station_pages():
    hub = {
        "path": "station/",
        "title": "서울 지하철역 안내｜역세권 출장마사지 방문 기준｜간다GO",
        "desc": "서울 1~9호선 주요 환승역·거점역의 역세권 방문 기준과 인접 생활권·행정동을 안내합니다.",
        "h1": "서울 지하철역 안내",
        "breadcrumb": [("지하철역 안내", None)],
        "body": (
            "<section><h2>역세권으로 보는 방문 기준</h2>"
            "<p>역 페이지는 역명 기준 1개만 두며, 환승역도 노선·출구별로 나누지 않습니다. "
            "역명보다 실제 방문 주소가 더 중요하므로, 역 주변 생활권과 함께 확인하세요.</p>"
            + _links([(s["name"], f"/station/{s['slug']}/") for s in STATIONS])
            + "</section>"
        ),
    }
    pages = [hub]
    for s in STATIONS:
        body = f"<p class=\"lead\">{s['intro']}</p>"
        if s.get("life"):
            body += (
                f"<section><h2>{s['name']} 인접 생활권</h2>"
                f"<p>{s['name']}는 {s['transfer']}으로, 아래 생활권과 행정동이 인접합니다.</p>"
                + _links(s["life"]) + "</section>"
            )
        else:
            body += (
                f"<section><h2>{s['name']} 인접 지역</h2>"
                f"<p>{s['name']}는 {s['transfer']}으로, 아래 자치구·행정동이 인접합니다.</p>"
                + _links(s["district"]) + "</section>"
            )
        if s.get("detail"):
            body += (
                f"<section><h2>{s['name']} 주변 방문 안내</h2>"
                f"<p>{s['detail']}</p></section>"
            )
        if s.get("detail2"):
            body += (
                f"<section><h2>{s['name']}에서 예약 시 알아두면 좋은 점</h2>"
                f"<p>{s['detail2']}</p></section>"
            )
        body += "<section><h2>가까운 행정동</h2>" + _ul(s["dongs"]) + "</section>"
        body += (
            "<section><h2>이용 장소별 확인사항</h2>"
            "<p>역 주변은 오피스텔·호텔·상가가 섞여 있어 장소별 확인이 필요합니다.</p>"
            + _links([
                ("오피스텔 이용", "/use/officetel/"),
                ("호텔·숙소 이용", "/use/hotel/"),
                ("역세권 이용", "/use/station-area/"),
            ])
            + "</section>"
        )
        body += (
            f"<section><h2>{s['name']} 역세권 예약, 이렇게 안내해주세요</h2>"
            f"<p>{s['name']}처럼 유동인구가 많은 역세권은 '역 근처'라는 안내만으로는 비슷한 건물 사이에서 "
            "위치를 특정하기 어렵습니다. 환승역의 경우 출구가 여러 곳이고 노선마다 분위기가 달라, 가까운 "
            "출구 번호를 기준으로 알려주시면 도착 시간을 크게 줄일 수 있습니다. 여기에 더해 정확한 도로명 "
            "주소와 건물명, 그리고 건물 1층의 상호나 가까운 랜드마크(편의점·카페·큰 건물 등)를 함께 "
            "알려주시면 더욱 정확합니다. 방문 장소가 오피스텔·오피스인지, 호텔·숙소인지, 아파트·주거인지에 "
            "따라 확인할 내용이 달라지므로 건물 유형도 미리 알려주세요. 오피스·오피스텔은 방문자 출입 등록과 "
            "카드키 동행 여부, 야간·주말 출입 가능 시간을, 호텔·숙소는 객실 번호와 예약자 이름을, 아파트는 "
            "공동현관 비밀번호와 동·호수, 방문 차량 등록 여부를 함께 확인하면 예약이 한결 수월합니다. "
            "출퇴근 시간대나 주말 저녁처럼 역 주변이 혼잡한 시간에는 도착 시간을 여유 있게 잡는 것이 좋습니다. "
            "참고로 환승역이라도 역 페이지는 노선·출구별로 따로 두지 않고 역명 기준 한 곳으로만 안내하므로, "
            "실제 방문 위치는 위의 생활권·행정동 안내와 함께 정확한 주소로 확인하시는 것이 가장 빠릅니다.</p>"
            "</section>"
        )
        body += _checklist(CHECKLIST_BASE)
        related = list(s["district"]) + list(s["life"]) + [
            ("지하철역 안내 전체", "/station/"),
            ("예약 전 확인사항", "/check/"),
        ]
        body += "<section><h2>관련 지역 보기</h2>" + _links(related) + "</section>"
        body += "<section><h2>운영 기준</h2>" + OPERATION_NOTE + "</section>"
        pages.append({
            "path": f"station/{s['slug']}/",
            "title": f"{s['name']} 출장마사지｜인접 생활권·방문 안내｜간다GO",
            "desc": f"{s['name']} 주변 출장마사지·홈타이 인접 생활권과 예약 전 확인사항을 안내합니다."[:80],
            "h1": f"{s['name']} 출장마사지 · 인접 생활권 안내",
            "breadcrumb": [("지하철역 안내", "/station/"), (s["name"], None)],
            "body": body,
            "faq": [
                (f"{s['name']} 근처라고만 하면 되나요?", "역·출구에 더해 건물명과 동·호수를 알려주시면 도착이 정확하고 빠릅니다."),
                ("환승역은 출구별로 나뉘나요?", "아니요. 역명 기준 한 곳으로 안내하며, 정확한 위치는 방문 주소로 확인합니다."),
            ],
        })
    return pages
